import 'package:flutter/material.dart';
class AppTheme {static const forest=Color(0xFF1E4D38),cream=Color(0xFFF9F7EE),soft=Color(0xFFE5EDDF),warm=Color(0xFFB98255); static ThemeData get light {final scheme=ColorScheme.fromSeed(seedColor:forest,brightness:Brightness.light).copyWith(surface:cream,primary:forest,secondary:Color(0xFF84A98C));return ThemeData(useMaterial3:true,colorScheme:scheme,scaffoldBackgroundColor:cream,cardTheme:CardTheme(color:Colors.white,elevation:1,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(20))),appBarTheme:const AppBarTheme(backgroundColor:cream,foregroundColor:forest,elevation:0));}}
